<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';import { BadgeAlert, Plus, RefreshCw, Search } from 'lucide-vue-next';import { ElMessage, ElMessageBox } from 'element-plus';import { api } from '../api';import OperationsMap from '../components/OperationsMap.vue';import PageHeader from '../components/PageHeader.vue';import { useSessionStore } from '../stores/session';import { useRoute } from 'vue-router';import type { PageData } from '../types';
const session=useSessionStore(),route=useRoute(),loading=ref(false),saving=ref(false),error=ref(''),rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref(route.path.endsWith('/rectifications')?'RECTIFYING':''),type=ref(''),level=ref(''),enterpriseId=ref(''),drawer=ref(false),detail=ref<any>(null),dialog=ref(false);const options=reactive<any>({vehicles:[],enterprises:[]});const isEnterprise=computed(()=>session.user?.portal==='ENTERPRISE');const isRectification=computed(()=>route.path.endsWith('/rectifications'));const canCreate=computed(()=>session.user?.permissions.includes('safety:violation:write'));const form=reactive({vehicleId:'',violationType:'OVERSPEED',level:'MEDIUM',title:'',description:'',longitude:120.012,latitude:30.286,occurredAt:''});let timer:number|undefined;const typeText=(v:string)=>({OVERSPEED:'超速',OUT_OF_BOUNDS:'越界',NO_ENTRY:'进入禁行区',OVERTIME:'超时运行',ILLEGAL_OPERATION:'违规运营',OTHER:'其他违规'}as any)[v]??v;const levelText=(v:string)=>({LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'重大'}as any)[v]??v;const statusText=(v:string)=>({PENDING_DETERMINATION:'待认定',CONFIRMED:'已认定',RECTIFYING:'整改中',PENDING_REVIEW:'待复核',CLOSED:'已关闭'}as any)[v]??v;const fmt=(v:string)=>new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
async function loadOptions(){Object.assign(options,await api<any>('/safety/options'))}async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams({page:String(page.value),pageSize:'20'});for(const[k,v]of Object.entries({q:q.value,status:status.value,type:type.value,level:level.value,enterpriseId:enterpriseId.value}))if(v)p.set(k,v);const data=await api<PageData<any>>(`/safety/violations?${p}`);rows.value=data.items;total.value=data.total}catch(reason){error.value=reason instanceof Error?reason.message:'违规记录加载失败'}finally{loading.value=false}}watch([q,status,type,level,enterpriseId],()=>{page.value=1;clearTimeout(timer);timer=window.setTimeout(load,180)});watch(page,load);watch(()=>route.path,()=>{status.value=route.path.endsWith('/rectifications')?'RECTIFYING':'';load()});onMounted(()=>Promise.all([load(),loadOptions()]));async function open(row:any){drawer.value=true;detail.value=await api<any>(`/safety/violations/${row.id}`)}
function nextAction(row:any){if(isEnterprise.value)return row.status==='RECTIFYING'?['SUBMIT_RECTIFICATION','提交整改反馈']:null;return ({PENDING_DETERMINATION:['CONFIRM','认定违规'],CONFIRMED:['REQUEST_RECTIFICATION','要求整改'],PENDING_REVIEW:['APPROVE','复核通过']}as any)[row.status]??null}async function act(row:any,forced?:string){const action=forced?[forced,forced==='RETURN'?'退回整改':'处理']:nextAction(row);if(!action)return;let comment='';try{comment=(await ElMessageBox.prompt(action[0]==='SUBMIT_RECTIFICATION'?'填写整改措施、完成情况和佐证说明。':'填写认定依据或处理意见。',action[1],{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请输入说明'})).value}catch{return}await api(`/safety/violations/${row.id}/actions`,{method:'POST',body:JSON.stringify({action:action[0],comment})});ElMessage.success(`${action[1]}成功`);detail.value=await api<any>(`/safety/violations/${row.id}`);await load()}
function openCreate(){Object.assign(form,{vehicleId:options.vehicles[0]?.id??'',violationType:'OVERSPEED',level:'MEDIUM',title:'',description:'',longitude:120.012,latitude:30.286,occurredAt:new Date().toISOString().slice(0,16)});dialog.value=true}async function create(){if(!form.vehicleId||!form.title||!form.description)return ElMessage.warning('请填写车辆、标题和违规事实');saving.value=true;try{await api('/safety/violations',{method:'POST',body:JSON.stringify({...form,occurredAt:new Date(form.occurredAt).toISOString()})});ElMessage.success('违规记录已登记，等待认定');dialog.value=false;await load()}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'登记失败')}finally{saving.value=false}}
</script>
<template><PageHeader :title="isRectification?'整改反馈':isEnterprise?'违规记录':'违规管理'" :description="isEnterprise?'查看本企业违规认定，按要求提交可复核的整改反馈。':'统一完成违规认定、整改要求、企业反馈和监管复核。'" :count="total"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button v-if="canCreate" type="primary" :icon="Plus" @click="openCreate">登记违规</el-button></PageHeader><div class="table-toolbar safety-toolbar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索违规编号、标题或车辆"/><el-select v-model="type" clearable placeholder="全部类型"><el-option v-for="item in ['OVERSPEED','OUT_OF_BOUNDS','NO_ENTRY','OVERTIME','ILLEGAL_OPERATION','OTHER']" :key="item" :label="typeText(item)" :value="item"/></el-select><el-select v-model="level" clearable placeholder="全部等级"><el-option v-for="item in ['CRITICAL','HIGH','MEDIUM','LOW']" :key="item" :label="levelText(item)" :value="item"/></el-select><el-select v-model="status" clearable placeholder="全部状态"><el-option v-for="item in ['PENDING_DETERMINATION','CONFIRMED','RECTIFYING','PENDING_REVIEW','CLOSED']" :key="item" :label="statusText(item)" :value="item"/></el-select><el-select v-if="!isEnterprise" v-model="enterpriseId" clearable filterable placeholder="全部企业"><el-option v-for="item in options.enterprises" :key="item.id" :label="item.name" :value="item.id"/></el-select></div><div v-if="error" class="error-state"><strong>违规记录暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else><el-table v-loading="loading" :data="rows" row-key="id" empty-text="暂无符合条件的违规记录"><el-table-column label="违规事项" min-width="250"><template #default="{row}"><button class="table-link" @click="open(row)"><strong>{{row.title}}</strong><span>{{row.businessNo}} · {{typeText(row.violationType)}}</span></button></template></el-table-column><el-table-column label="等级" width="82"><template #default="{row}"><span class="risk-level" :class="row.level.toLowerCase()"><i></i>{{levelText(row.level)}}</span></template></el-table-column><el-table-column label="车辆" min-width="155"><template #default="{row}"><div class="identity-cell"><strong>{{row.vehicle.name}}</strong><span>{{row.vehicle.businessNo}}</span></div></template></el-table-column><el-table-column v-if="!isEnterprise" label="企业" min-width="185"><template #default="{row}">{{row.enterprise.name}}</template></el-table-column><el-table-column label="发生时间" width="165"><template #default="{row}">{{fmt(row.occurredAt)}}</template></el-table-column><el-table-column label="认定 / 整改" min-width="220"><template #default="{row}"><div class="identity-cell"><strong>{{row.determination||'等待监管认定'}}</strong><span>{{row.rectification||'尚未提交整改反馈'}}</span></div></template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag size="small" :type="row.status==='CLOSED'?'success':row.status==='PENDING_REVIEW'?'warning':'primary'">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="open(row)">查看处理</el-button></template></el-table-column></el-table><div class="pagination-row"><span>当前显示 {{rows.length}} / {{total}}</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next"/></div></template>
<el-drawer v-model="drawer" size="800px" destroy-on-close><template #header><div class="archive-drawer-title"><div><span>{{detail?.businessNo}}</span><h2>违规处理详情</h2></div><el-tag v-if="detail">{{statusText(detail.status)}}</el-tag></div></template><template v-if="detail"><div class="case-hero" :class="detail.level.toLowerCase()"><BadgeAlert :size="23"/><div><span>{{typeText(detail.violationType)}} · {{levelText(detail.level)}}等级</span><strong>{{detail.title}}</strong><small>{{fmt(detail.occurredAt)}}</small></div></div><OperationsMap v-if="detail.operationRecord?.trackPoints?.length" mode="trajectory" :track="detail.operationRecord.trackPoints" height="340px"/><dl class="detail-grid"><div><dt>违规车辆</dt><dd>{{detail.vehicle.name}} · {{detail.vehicle.businessNo}}</dd></div><div><dt>所属企业</dt><dd>{{detail.enterprise.name}}</dd></div><div class="detail-span-2"><dt>违规事实</dt><dd>{{detail.description}}</dd></div><div class="detail-span-2"><dt>监管认定</dt><dd>{{detail.determination||'尚未认定'}}</dd></div><div class="detail-span-2"><dt>企业整改反馈</dt><dd>{{detail.rectification||'尚未反馈'}}</dd></div><div class="detail-span-2"><dt>复核意见</dt><dd>{{detail.reviewComment||'尚未复核'}}</dd></div></dl><div class="drawer-actions"><el-button v-if="!isEnterprise&&detail.status==='PENDING_REVIEW'" @click="act(detail,'RETURN')">退回整改</el-button><el-button v-if="nextAction(detail)" type="primary" @click="act(detail)">{{nextAction(detail)[1]}}</el-button></div></template></el-drawer>
<el-dialog v-model="dialog" title="登记违规" width="680px"><div class="form-grid"><el-form-item label="涉及车辆" required><el-select v-model="form.vehicleId" filterable><el-option v-for="item in options.vehicles" :key="item.id" :label="`${item.name} · ${item.businessNo}`" :value="item.id"/></el-select></el-form-item><el-form-item label="发生时间" required><el-date-picker v-model="form.occurredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm"/></el-form-item><el-form-item label="违规类型"><el-select v-model="form.violationType"><el-option v-for="item in ['OVERSPEED','OUT_OF_BOUNDS','NO_ENTRY','OVERTIME','ILLEGAL_OPERATION','OTHER']" :key="item" :label="typeText(item)" :value="item"/></el-select></el-form-item><el-form-item label="违规等级"><el-select v-model="form.level"><el-option v-for="item in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="item" :label="levelText(item)" :value="item"/></el-select></el-form-item><el-form-item class="form-span-2" label="事项标题" required><el-input v-model.trim="form.title"/></el-form-item><el-form-item class="form-span-2" label="违规事实" required><el-input v-model.trim="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6" :step="0.001"/></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6" :step="0.001"/></el-form-item></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">保存记录</el-button></template></el-dialog></template>
